def is_palindrome(s):
    s = s.lower().replace(" ", "")
    return s == s[::-1]
def factorial(n):
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result
def fibonacci(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a
def count_vowels(text):
    return sum(1 for ch in text.lower() if ch in "aeiou")
def flatten(nested):
    flat = []
    for item in nested:
        if isinstance(item, list):
            flat.extend(flatten(item))
        else:
            flat.append(item)
    return flat
def merge_dicts(a, b):
    out = dict(a)
    for key, value in b.items():
        out[key] = value
    return out
def binary_search(items, target):
    lo, hi = 0, len(items) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if items[mid] == target:
            return mid
        if items[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1
def unique_sorted(values):
    return sorted(set(values))
def word_frequencies(text):
    freq = {}
    for word in text.split():
        freq[word] = freq.get(word, 0) + 1
    return freq
def gcd(a, b):
    while b:
        a, b = b, a % b
    return abs(a)
def chunk_list(items, size):
    return [items[i:i + size] for i in range(0, len(items), size)]
def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True
def reverse_words(sentence):
    return " ".join(sentence.split()[::-1])
def running_sum(numbers):
    total = 0
    out = []
    for n in numbers:
        total += n
        out.append(total)
    return out
def max_pair_product(nums):
    best = None
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            p = nums[i] * nums[j]
            if best is None or p > best:
                best = p
    return best
class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        return self.items.pop()

    def peek(self):
        return self.items[-1]
def celsius_to_fahrenheit(c):
    return c * 9 / 5 + 32
def transpose(matrix):
    return [list(row) for row in zip(*matrix)]
def remove_duplicates_keep_order(items):
    seen = set()
    out = []
    for item in items:
        if item not in seen:
            seen.add(item)
            out.append(item)
    return out
def title_case(text):
    return " ".join(word.capitalize() for word in text.split())
def dot_product(a, b):
    if len(a) != len(b):
        raise ValueError("length mismatch")
    return sum(x * y for x, y in zip(a, b))
def caesar_cipher(text, shift):
    out = []
    for ch in text:
        if ch.isalpha():
            base = ord("A") if ch.isupper() else ord("a")
            out.append(chr((ord(ch) - base + shift) % 26 + base))
        else:
            out.append(ch)
    return "".join(out)
def median(values):
    ordered = sorted(values)
    n = len(ordered)
    mid = n // 2
    if n % 2:
        return ordered[mid]
    return (ordered[mid - 1] + ordered[mid]) / 2
def count_lines_with(path_lines, needle):
    count = 0
    for line in path_lines:
        if needle in line:
            count += 1
    return count
def invert_dict(d):
    return {value: key for key, value in d.items()}
def clamp(value, lo, hi):
    if value < lo:
        return lo
    if value > hi:
        return hi
    return value
def moving_average(values, window):
    out = []
    for i in range(len(values) - window + 1):
        out.append(sum(values[i:i + window]) / window)
    return out
def parse_key_values(text):
    result = {}
    for pair in text.split(","):
        if "=" not in pair:
            continue
        key, value = pair.split("=", 1)
        result[key.strip()] = value.strip()
    return result
def longest_word(sentence):
    words = sentence.split()
    if not words:
        return ""
    return max(words, key=len)
def sum_of_digits(n):
    n = abs(n)
    total = 0
    while n:
        total += n % 10
        n //= 10
    return total
def rotate_left(items, k):
    if not items:
        return []
    k %= len(items)
    return items[k:] + items[:k]
def is_anagram(a, b):
    return sorted(a.lower()) == sorted(b.lower())
